{
  "root_causes": [
    {
      "service": "search",
      "fault_kind": "http_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT attr_k8s_service_name AS svc, span_name, attr_span_kind AS kind, count(*) AS n, approx_quantile(duration/1e6,0.5) AS p50_ms, approx_quantile(duration/1e6,0.95) AS p95_ms FROM abnormal_traces WHERE attr_k8s_service_name='search' AND span_name='rate.Rate/GetRates' AND attr_span_kind='Client' GROUP BY ALL",
          "claim": "search's outgoing rate.Rate/GetRates client spans take about 1.8s p50 and 2.8s p95 during the incident."
        },
        {
          "kind": "trace",
          "sql": "SELECT attr_k8s_service_name AS svc, span_name, count(*) AS n, approx_quantile(duration/1e6,0.5) AS p50_ms, approx_quantile(duration/1e6,0.95) AS p95_ms FROM abnormal_traces WHERE attr_k8s_service_name='rate' AND span_name='rate.Rate/GetRates' AND attr_span_kind='Server' GROUP BY ALL",
          "claim": "rate's own server spans stay fast (p95 about 1ms), so the delay is not inside rate."
        },
        {
          "kind": "trace",
          "sql": "SELECT attr_k8s_service_name AS svc, span_name, attr_span_kind AS kind, count(*) AS n, approx_quantile(duration/1e6,0.95) AS p95_ms FROM abnormal_traces WHERE attr_k8s_service_name='search' AND span_name='geo.Geo/Nearby' AND attr_span_kind='Client' GROUP BY ALL",
          "claim": "search's calls to geo stay normal (p95 about 0.65ms) in the same period, so the fault is specific to the rate path."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "search",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT attr_k8s_service_name AS svc, span_name, attr_span_kind AS kind, count(*) AS n, approx_quantile(duration/1e6,0.95) AS p95_ms, sum(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) AS errs FROM abnormal_traces WHERE (attr_k8s_service_name='frontend' AND span_name='search.Search/Nearby') OR (attr_k8s_service_name='search' AND span_name='search.Search/Nearby' AND attr_span_kind='Server') GROUP BY ALL",
          "claim": "frontend's search.Search/Nearby client calls and search's server spans both reach about 2.8s p95, with frontend's own time flat."
        }
      ]
    }
  ]
}

